//! Hue / saturation / lightness.
//!
//! The components are stored exactly as given: the constructor neither wraps
//! the hue into `[0, 360)` nor clamps saturation and lightness, which is why a
//! hue of 720 stays 720 and shows up in the conversions below.

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Hsl {
    pub h: f64,
    pub s: f64,
    pub l: f64,
}

impl Hsl {
    pub fn new(h: f64, s: f64, l: f64) -> Self {
        Hsl { h, s, l }
    }
}

//! `std::cout << float`, which is glibc `printf("%g", (double) v)` at the
//! default stream precision of 6.
//!
//! Every `f32` has a finite exact decimal expansion, so this expands the value
//! exactly and then rounds that expansion to six significant digits. Working
//! from the exact digits is what makes ties come out right: glibc rounds half
//! to even, so `100000.5` prints as `100000` while `100001.5` prints as
//! `100002`. Choosing `%e` or `%f` and trimming trailing zeros then follows
//! the usual `%g` rules.

use super::super::bignum::BigUint;

/// Significant digits `%g` keeps at the default precision.
const P: usize = 6;

pub fn format_g6(v: f32) -> String {
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    let sign = if v.is_sign_negative() { "-" } else { "" };
    if v.is_infinite() {
        return format!("{}inf", sign);
    }

    let bits = v.to_bits();
    let frac = bits & 0x7f_ffff;
    let biased = ((bits >> 23) & 0xff) as i32;
    if biased == 0 && frac == 0 {
        return format!("{}0", sign);
    }
    // |v| = m * 2^e with m an integer.
    let (m, e) = if biased == 0 {
        (frac, -149i32)
    } else {
        (frac | (1 << 23), biased - 127 - 23)
    };

    // Exact decimal expansion: |v| = digits * 10^scale.
    let mut n = BigUint::from_u64(u64::from(m));
    let scale = if e >= 0 {
        n.shl_bits(e as u64);
        0i64
    } else {
        n.mul_pow5((-e) as u32);
        i64::from(e)
    };
    let ds = n.to_decimal_string();
    let db = ds.as_bytes();

    // Decimal exponent of the leading digit, then round to P digits.
    let mut x = db.len() as i64 - 1 + scale;
    let mut sig: Vec<u8> = Vec::with_capacity(P);
    if db.len() <= P {
        sig.extend_from_slice(db);
        sig.resize(P, b'0');
    } else {
        sig.extend_from_slice(&db[..P]);
        let next = db[P];
        let rest_nonzero = db[P + 1..].iter().any(|&d| d != b'0');
        let tie_up = rest_nonzero || (sig[P - 1] - b'0') % 2 == 1;
        if next > b'5' || (next == b'5' && tie_up) {
            round_up(&mut sig, &mut x);
        }
    }

    let body = if x < -4 || x >= P as i64 {
        // %e with precision P-1, trailing zeros trimmed.
        let mut mant = String::new();
        mant.push(sig[0] as char);
        let f = trim_zeros(&sig[1..]);
        if !f.is_empty() {
            mant.push('.');
            mant.push_str(&f);
        }
        format!("{}e{}{:02}", mant, if x < 0 { '-' } else { '+' }, x.abs())
    } else if x >= 0 {
        // %f with the point inside the digits we have.
        let cut = x as usize + 1;
        let int = String::from_utf8_lossy(&sig[..cut]).into_owned();
        let f = trim_zeros(&sig[cut..]);
        if f.is_empty() {
            int
        } else {
            format!("{}.{}", int, f)
        }
    } else {
        // %f with leading zeros between the point and the digits.
        let mut fdigits = vec![b'0'; (-x - 1) as usize];
        fdigits.extend_from_slice(&sig);
        format!("0.{}", trim_zeros(&fdigits))
    };
    format!("{}{}", sign, body)
}

/// Increment the digit string, carrying; an all-nines string becomes 1 followed
/// by zeros and bumps the exponent.
fn round_up(sig: &mut Vec<u8>, x: &mut i64) {
    for i in (0..sig.len()).rev() {
        if sig[i] == b'9' {
            sig[i] = b'0';
        } else {
            sig[i] += 1;
            return;
        }
    }
    sig.insert(0, b'1');
    sig.truncate(P);
    *x += 1;
}

fn trim_zeros(d: &[u8]) -> String {
    let mut end = d.len();
    while end > 0 && d[end - 1] == b'0' {
        end -= 1;
    }
    String::from_utf8_lossy(&d[..end]).into_owned()
}

